const brands=[
 {id:'tsukada',name:'塚田農場',en:'TSUKADA NOJO',tag:'大地の恵みをみんなで囲む。',image:'jidori.png',alt:'炭火で焼き上げた地鶏',category:'地鶏・郷土料理',food:'地鶏炭火焼',region:'miyazaki',story:'jidori',site:'https://www.tsukadanojo.jp/',store:'https://shop.tsukadanojo.jp/',intro:'宮崎の地鶏と九州の郷土料理を気の置けない仲間と囲む。産地のおいしさを楽しむ食卓です。',origin:'宮崎県の塚田地区にある自社養鶏場。その名前を受け継いだ店が、塚田農場です。生産者と店をつなぐ仕組みを育てながら、地鶏をもっと身近に楽しめる食へと届けてきました。',foodText:'炭火の香りをまとった地鶏を熱いうちに味わいます。一皿をみんなで囲むと土地の話や今日の出来事で自然と会話がはずみます。',reason:'気の置けない人とにぎやかに一皿を囲みたい日におすすめです。塚田農場では地鶏炭火焼と九州の味を楽しめます。'},
 {id:'yonpachi',name:'四十八漁場',en:'YONPACHI GYOJOU',tag:'今日の海を味わう。',image:'fish.jpg',alt:'四十八漁場の刺身の盛り合わせ',category:'鮮魚・日本酒',food:'鮮魚のお刺身',region:'sea',story:'sea',site:'https://www.48gyojyou.com/',store:'https://www.48gyojyou.com/',intro:'全国の漁師や漁協・産地市場とつながる店で魚と日本酒を楽しむ。まだ知らない海のおいしさに出会えます。',origin:'魚を食べる楽しみを未来にもつないでいきたい。四十八漁場は、そんな想いを店名に込めたブランドです。産地と直接つながり、魚の手当てから流通まで、おいしさを届ける道のりを大切にしています。',foodText:'その日に出会える魚をお刺身で味わいます。一皿をきっかけに魚の種類や味わいと産地をもっと知りたくなります。内容は店舗・時期・水揚げによって異なります。',reason:'旬の味や知らない食材との出会いを楽しみたい日におすすめです。四十八漁場では産地とつながる鮮魚と日本酒を味わえます。'},
 {id:'yakitori',name:'焼鳥つかだ',en:'YAKITORI TSUKADA',tag:'一本ずつ丁寧に味わう時間。',image:'yakitori-a.jpg',alt:'炭火で一本ずつ焼き上げる焼鳥',category:'地鶏・焼鳥',food:'みやざき地頭鶏の焼鳥',region:'miyazaki',story:'craft',site:'https://www.yakitori-tsukada.jp/',store:'https://www.yakitori-tsukada.jp/',intro:'職人が炭火で丹念に焼くみやざき地頭鶏。地鶏の持ち味を一本ずつゆっくり味わえます。',origin:'生販直結で培った地鶏への知識を焼鳥で表現する店です。焼鳥つかだは、産地とつながるAPの土台から、地鶏を楽しむもう一つの時間をつくっています。',foodText:'串打ちから火入れまで、一本ごとに手をかける。目の前の焼鳥から素材と炭火に向き合う仕事を感じてください。',reason:'落ち着いた空間で料理をじっくり味わいたい日におすすめです。焼鳥つかだでは職人の炭火仕事を楽しめます。'}
];
const pillars=['食をつくる','産地とつくる','店をつくる','人とつくる','未来をつくる'];
const stories=[
 {id:'jidori',category:0,no:'01',title:'一羽の地鶏が塚田農場の一皿になるまで',image:'flame.png',alt:'地鶏を焼き上げる炭火の炎',sub:'産地から厨房までのおいしさの道のり',brand:'tsukada',intro:'高く上がる炎で仕上げる香ばしい一皿。そのおいしさは厨房だけで生まれたものではありません。地鶏を育てる日々から食卓までをたどると、APが大切にする「生販直結」が見えてきます。',sections:[['01　はじまりは一羽を育てること','地鶏炭火焼の物語は、鶏を育てるところから始まります。親鳥づくりからヒナの育成を経て契約農家での飼育へと進みます。食材を仕入れるだけでは見えてこない長い時間が、一皿の前にあります。','chickens.png'],['02　産地の仕事を店につなぐ','育てる人と料理する人がつながっています。APの生販直結は、生産から加工・流通・販売までを一貫して考える仕組みです。産地の価値を受け取ってお客様まで届ける道筋もおいしさの一部です。','farm.png'],['03　最後は炭と炎で仕上げる','届いた地鶏を焼き上げるのは厨房の料理人です。炭の状態を見ながら炎を扱い、仕上がりを見極めます。育てる仕事から焼く仕事へとつながってきた一羽が、ここで一皿になります。','jidori.png']],ending:'食べるときに少しだけ産地を思い浮かべると、いつもの一皿が違って見えるかもしれません。'},
 {id:'sea',category:1,no:'02',title:'魚のおいしさは海の上から始まる',image:'fish.jpg',alt:'四十八漁場の鮮魚',sub:'四十八漁場の先にある海',brand:'yonpachi',intro:'お刺身の向こう側には、漁師の仕事があります。四十八漁場は全国の産地とつながり、魚のおいしさを食卓まで届けています。',sections:[['見えない仕事が味をつくる','水揚げされた魚に、どんな手当てをするか。どう運ぶか。四十八漁場では、船上から始まる処理と独自の流通を大切にしています。鮮魚の価値を産地から店までつないでいます。','fish.jpg'],['知らない魚に出会う楽しみ。','都心ではあまり見かけない魚も、味わえば発見になる。食べる魚の選択肢が広がることは、海と食卓の関係を考えるきっかけにもなります。次の一皿で、産地の話を聞いてみませんか。',null]],ending:'今日おいしかった魚を未来も楽しめるように、食べることを通して産地との関係を育てていきます。'},
 {id:'craft',category:0,no:'03',title:'同じ地鶏から違う一皿が生まれる理由',image:'yakitori-a.jpg',alt:'焼鳥つかだの炭火調理',sub:'焼鳥つかだで一本ずつ向き合う仕事',brand:'yakitori',intro:'豪快な炭火焼と丹念に焼き上げる焼鳥では、同じ産地の食材から違う食体験が生まれます。ブランドの多様さは、食材の可能性の多様さでもあります。',sections:[['一本の焼鳥ができるまで','焼く前には食材を切り分けて串を打ちます。一本の焼鳥には、目に見えない準備があります。みやざき地頭鶏の魅力をどう引き出すか。職人の仕事が食材とお客様をつなぎます。','yakitori-c.jpg'],['その場で味わう時間まで。','料理を食べる空間や会話の距離に炭火の気配も重なります。焼鳥つかだが届けるのは一本の焼鳥とそれを楽しむ時間です。産地の価値は、店という場所で新しい表情を見せます。','yakitori-b.jpg']],ending:'ひとつの素材にもさまざまな味わい方があります。その違いを楽しめるのがAPのブランドを巡る面白さです。'},
 {id:'brand',category:2,no:'04',title:'ひとつの思想から複数の食卓が生まれる',image:'yakitori-b.jpg',alt:'焼鳥つかだの店内',sub:'ブランドの違いからAPを知る',brand:'yakitori',intro:'塚田農場・四十八漁場・焼鳥つかだでは料理や空間が異なり、過ごし方も変わります。その背景には、食の価値をどう届けるかという共通の問いがあります。',sections:[['ブランドごとに食の楽しみ方が変わる','仲間と地鶏を囲む日もあれば、魚と日本酒を味わう日もある。一本の焼鳥にゆっくり向き合う夜もある。多様なブランドは、食と人が出会う入口を増やしています。',null],['店の向こうには産地がある','表現が変わっても、素材に向き合うことは変わりません。気になったブランドの料理をたどると産地が見えてきます。ひとつの店をきっかけにAPの世界を知ることができます。','farm.png']],ending:'今日はどんな食の時間を過ごしますか。'},
 {id:'people',category:3,no:'05',title:'料理を届ける人は産地の背景も伝えている',image:'fictional-chef.png',alt:'高橋直人の写真',sub:'料理人を通して食の仕事を描く',brand:'tsukada',intro:'食の仕事は、皿の上だけには収まりません。素材と作り手を知ったうえで背景までお客様に伝える。料理人・高橋直人のストーリーから、その仕事を描きます。',sections:[['おいしさの理由まで自分の言葉で伝える','「どう育った食材なのか。それを知ると、料理の扱い方も、伝え方も変わる気がします」。高橋直人は、そう語る料理人です。食と産地と人をつなぐ人物の物語です。',null]],ending:'料理をつくる人の仕事を知ると一皿の見え方も変わります。食をつくる人のページでも紹介しています。'},
 {id:'future',category:4,no:'06',title:'食の未来は産地の未来につながっている',image:'farm.png',alt:'塚田農場公式サイトに掲載された契約農家の皆さん',sub:'FOOD CREATIVE FIRMが目指すもの。',brand:'yonpachi',intro:'おいしいものをこれからも楽しめるように、食文化や飲食人と生産地の未来を一緒に考えます。APが掲げるFOOD CREATIVE FIRMという姿を、身近な食から見つめます。',sections:[['つくる人が続けられる仕組みを考える','食卓に料理がある当たり前の毎日を生産者の営みが支えています。生産と販売がつながる仕組みを持つAPの活動は、産地と店を別々に考えない視点につながっています。',null],['おいしさを次の世代へつなぐ','四十八漁場は魚食を未来につなぎ、地鶏を扱うブランドはその可能性を広げています。具体的な店と料理を通して食の課題を考える積み重ねが未来を考える入口になります。','fish.jpg']],ending:'これは新しい事業計画の発表ではなく、公式の思想をもとにした編集企画です。'}
];
const questions=[{title:'今日はどんなふうに過ごしたい？',options:['気の置けない仲間とにぎやかに','知らないおいしさを誰かと楽しむ','落ち着いて一皿ずつ味わう']},{title:'今いちばん惹かれるのは？',options:['炭火が香る力強い地鶏','その日に届いた海の恵み','職人が焼き上げる一本']},{title:'食事にもうひとつ求めるなら？',options:['自然と会話がはずむこと','季節や産地を感じること','つくる人の仕事を感じること']}];
